import pytest
from freebusy import free_slots

WEEKDAYS = ("mon", "tue", "wed", "thu", "fri")
WEEKEND = ("sat", "sun")
ALL_DAYS = WEEKDAYS + WEEKEND


class TestBasicFunctionality:
    """Test fundamental free_slots behavior."""

    def test_one_attendee_single_free_window(self):
        """Single attendee with simple working hours."""
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEKDAYS}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_one_attendee_full_day_working(self):
        """Single attendee working all day."""
        alice = {"tz": "UTC", "hours": {d: ["00:00-24:00"] for d in ALL_DAYS}}
        result = free_slots([alice], "2025-06-02T10:00Z", "2025-06-02T12:00Z", 30)
        assert result == [("2025-06-02T10:00:00Z", "2025-06-02T12:00:00Z")]

    def test_one_attendee_no_working_hours(self):
        """Attendee with no working hours defined returns empty."""
        alice = {"tz": "UTC", "hours": {}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 30)
        assert result == []

    def test_no_overlap_in_search_window(self):
        """Search window outside working hours."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-02T08:00Z", 30)
        assert result == []

    def test_partial_overlap_with_search_window(self):
        """Search window partially overlaps working hours."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T12:00Z", "2025-06-02T20:00Z", 30)
        assert result == [("2025-06-02T12:00:00Z", "2025-06-02T17:00:00Z")]


class TestMultipleTimeZones:
    """Test scheduling across different time zones."""

    def test_two_time_zones_overlapping_hours(self):
        """Two attendees in different time zones with same working hours."""
        ny = {"tz": "America/New_York", "hours": {d: ["09:00-17:00"] for d in WEEKDAYS}}
        berlin = {"tz": "Europe/Berlin", "hours": {d: ["09:00-17:00"] for d in WEEKDAYS}}
        result = free_slots([ny, berlin], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        # NY is UTC-4 in June, Berlin is UTC+2
        # NY 09:00-17:00 is 13:00-21:00 UTC
        # Berlin 09:00-17:00 is 07:00-15:00 UTC
        # Overlap: 13:00-15:00 UTC
        assert result == [("2025-06-02T13:00:00Z", "2025-06-02T15:00:00Z")]

    def test_three_time_zones(self):
        """Three attendees across different time zones."""
        tokyo = {"tz": "Asia/Tokyo", "hours": {d: ["09:00-17:00"] for d in WEEKDAYS}}
        london = {"tz": "Europe/London", "hours": {d: ["09:00-17:00"] for d in WEEKDAYS}}
        la = {"tz": "America/Los_Angeles", "hours": {d: ["09:00-17:00"] for d in WEEKDAYS}}
        result = free_slots(
            [tokyo, london, la], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30
        )
        # Tokyo 09:00-17:00 is 00:00-08:00 UTC
        # London 09:00-17:00 is 08:00-16:00 UTC
        # LA 09:00-17:00 is 16:00-00:00 UTC next day
        # No overlap that lasts 30 minutes on 2025-06-02
        assert result == []

    def test_timezone_aware_timestamps(self):
        """Timestamps with different UTC offsets representing same instant."""
        alice = {"tz": "UTC", "hours": {d: ["10:00-20:00"] for d in WEEKDAYS}}
        # Both timestamps represent 2025-06-02T12:00:00Z
        result = free_slots([alice], "2025-06-02T12:00:00+00:00", "2025-06-02T13:00:00Z", 30)
        assert result == [("2025-06-02T12:00:00Z", "2025-06-02T13:00:00Z")]


class TestBusyPeriods:
    """Test handling of busy periods."""

    def test_one_busy_period_in_working_hours(self):
        """Single busy period removes time from available hours."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T12:00:00Z", "2025-06-02T13:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T13:00:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_multiple_overlapping_busy_periods(self):
        """Multiple overlapping busy periods are merged."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [
                ["2025-06-02T12:00:00Z", "2025-06-02T13:30:00Z"],
                ["2025-06-02T13:00:00Z", "2025-06-02T14:00:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T14:00:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_busy_period_covers_all_working_hours(self):
        """Busy period completely covers working hours."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T08:00:00Z", "2025-06-02T18:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == []

    def test_busy_period_outside_search_window(self):
        """Busy period outside search window doesn't affect result."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T18:00:00Z", "2025-06-02T19:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_busy_period_no_busy_key(self):
        """Missing 'busy' key means attendee has no busy periods."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_adjacent_busy_periods_not_merged(self):
        """Adjacent but non-overlapping busy periods remain separate."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [
                ["2025-06-02T12:00:00Z", "2025-06-02T13:00:00Z"],
                ["2025-06-02T13:00:00Z", "2025-06-02T14:00:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 30)
        # These should merge into one busy period
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T14:00:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_busy_at_attendee_timezone(self):
        """Busy periods are interpreted in UTC offset provided."""
        tokyo = {
            "tz": "Asia/Tokyo",
            "hours": {"mon": ["09:00-12:00"]},
            "busy": [["2025-06-02T09:30:00+09:00", "2025-06-02T10:45:00+09:00"]],
        }
        result = free_slots([tokyo], "2025-06-01T00:00Z", "2025-06-03T00:00Z", 60)
        # Tokyo 09:30-10:45 JST = 00:30-01:45 UTC
        # Tokyo 09:00-12:00 JST = 00:00-03:00 UTC
        # Free: 00:00-00:30 (30 min, too short) and 01:45-03:00 (75 min)
        assert result == [("2025-06-02T01:45:00Z", "2025-06-02T03:00:00Z")]


class TestMinMinutesFiltering:
    """Test min_minutes parameter."""

    def test_slot_shorter_than_min_minutes_excluded(self):
        """Slots shorter than min_minutes are not returned."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T12:00:00Z", "2025-06-02T12:20:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 30)
        # 12:00-12:20 is 20 minutes (too short)
        # 12:20-17:00 is 260 minutes (included)
        assert result == [("2025-06-02T12:20:00Z", "2025-06-02T17:00:00Z")]

    def test_slot_exactly_min_minutes_included(self):
        """Slots exactly min_minutes long are included."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T12:00:00Z", "2025-06-02T12:30:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 30)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T12:30:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_multiple_slots_filtered_by_min_minutes(self):
        """Multiple slots filtered based on min_minutes."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [
                ["2025-06-02T10:00:00Z", "2025-06-02T10:15:00Z"],
                ["2025-06-02T12:00:00Z", "2025-06-02T12:30:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 60)
        # 09:00-10:00 is 60 min (included)
        # 10:15-12:00 is 105 min (included)
        # 12:30-17:00 is 270 min (included)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z"),
            ("2025-06-02T10:15:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T12:30:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_min_minutes_one(self):
        """min_minutes=1 includes all non-zero duration slots."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T12:00:00Z", "2025-06-02T12:01:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 1)
        assert len(result) == 2
        assert result[0] == ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z")


class TestWeekdayHandling:
    """Test weekday-specific working hours."""

    def test_working_hours_only_on_monday(self):
        """Working hours only on Monday."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result_mon = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        result_tue = free_slots([alice], "2025-06-03T00:00Z", "2025-06-04T00:00Z", 30)
        assert result_mon == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]
        assert result_tue == []

    def test_weekdays_vs_weekends(self):
        """Different hours for weekdays and weekends."""
        alice = {
            "tz": "UTC",
            "hours": {
                "mon": ["09:00-17:00"],
                "tue": ["09:00-17:00"],
                "wed": ["09:00-17:00"],
                "thu": ["09:00-17:00"],
                "fri": ["09:00-17:00"],
                "sat": ["10:00-14:00"],
                "sun": ["10:00-14:00"],
            },
        }
        result_fri = free_slots([alice], "2025-06-06T00:00Z", "2025-06-07T00:00Z", 30)
        result_sat = free_slots([alice], "2025-06-07T00:00Z", "2025-06-08T00:00Z", 30)
        assert result_fri == [("2025-06-06T09:00:00Z", "2025-06-06T17:00:00Z")]
        assert result_sat == [("2025-06-07T10:00:00Z", "2025-06-07T14:00:00Z")]

    def test_multiple_entries_same_weekday(self):
        """Multiple non-overlapping working hour entries on same weekday."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-12:00", "13:00-17:00"]},
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T13:00:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_overlapping_entries_same_weekday(self):
        """Overlapping working hour entries on same weekday are merged."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-13:00", "12:00-17:00"]},
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        # Should merge into 09:00-17:00
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_empty_hours_list_for_weekday(self):
        """Empty hours list for a weekday means no working hours."""
        alice = {"tz": "UTC", "hours": {"mon": []}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == []


class TestCrossMidnightHours:
    """Test working hours that span midnight."""

    def test_cross_midnight_simple(self):
        """Working hours crossing midnight with end before start."""
        alice = {
            "tz": "UTC",
            "hours": {"fri": ["22:00-06:00"]},
        }
        result = free_slots([alice], "2025-06-06T00:00Z", "2025-06-08T00:00Z", 30)
        # Friday 22:00 UTC to Saturday 06:00 UTC
        assert result == [("2025-06-06T22:00:00Z", "2025-06-07T06:00:00Z")]

    def test_cross_midnight_end_24_00(self):
        """Working hours using 24:00 as end time."""
        alice = {
            "tz": "UTC",
            "hours": {"fri": ["22:00-24:00"]},
        }
        result = free_slots([alice], "2025-06-06T00:00Z", "2025-06-08T00:00Z", 30)
        # Friday 22:00 to Saturday 00:00 (which is 24:00 of Friday)
        assert result == [("2025-06-06T22:00:00Z", "2025-06-07T00:00:00Z")]

    def test_cross_midnight_saturday_continues_to_sunday(self):
        """Friday's cross-midnight hours extend into Saturday."""
        alice = {
            "tz": "UTC",
            "hours": {
                "fri": ["22:00-06:00"],
                "sat": ["22:00-06:00"],
            },
        }
        result = free_slots([alice], "2025-06-06T20:00Z", "2025-06-08T10:00Z", 30)
        # Friday 22:00 to Saturday 06:00, then Saturday 22:00 to Sunday 06:00
        assert result == [
            ("2025-06-06T22:00:00Z", "2025-06-07T06:00:00Z"),
            ("2025-06-07T22:00:00Z", "2025-06-08T06:00:00Z"),
        ]

    def test_cross_midnight_timezone_aware(self):
        """Cross-midnight in a specific timezone."""
        tokyo = {
            "tz": "Asia/Tokyo",
            "hours": {"fri": ["22:00-06:00"]},
        }
        result = free_slots([tokyo], "2025-06-06T00:00Z", "2025-06-08T00:00Z", 30)
        # Friday 22:00 JST = Friday 13:00 UTC
        # Saturday 06:00 JST = Friday 21:00 UTC
        # So working hours are Friday 13:00 UTC to Friday 21:00 UTC
        assert result == [("2025-06-06T13:00:00Z", "2025-06-06T21:00:00Z")]


class TestDaylightSavingTime:
    """Test handling of DST transitions."""

    def test_spring_forward_skipped_time(self):
        """Spring forward: skipped times are never covered by working hours."""
        ny = {
            "tz": "America/New_York",
            "hours": {"sun": ["02:30-04:00"]},
        }
        # 2025-03-09: clocks jump from 02:00 EST to 03:00 EDT at 07:00Z
        # 02:30-04:00 EST doesn't exist; becomes 03:00-04:00 EDT
        # 03:00-04:00 EDT = 07:00-08:00Z
        result = free_slots([ny], "2025-03-09T00:00Z", "2025-03-10T00:00Z", 1)
        assert result == [("2025-03-09T07:00:00Z", "2025-03-09T08:00:00Z")]

    def test_spring_forward_entry_before_skip(self):
        """Entry ending before the skipped times."""
        ny = {
            "tz": "America/New_York",
            "hours": {"sun": ["02:10-02:50"]},
        }
        # Skipped 02:00-03:00 EDT (before the jump), so this entry covers nothing
        result = free_slots([ny], "2025-03-09T00:00Z", "2025-03-10T00:00Z", 1)
        assert result == []

    def test_spring_forward_cross_midnight_entry(self):
        """Cross-midnight entry spanning the DST transition."""
        ny = {
            "tz": "America/New_York",
            "hours": {"sat": ["22:00-02:30"]},
        }
        # Saturday 22:00 EST to Sunday 02:30 EST
        # But Sunday clocks jump, so 02:30 EST doesn't exist
        # Saturday 22:00 EST = 03:00Z, Sunday 03:00 EDT = 07:00Z (after jump)
        result = free_slots([ny], "2025-03-08T00:00Z", "2025-03-10T00:00Z", 1)
        # Saturday 22:00 EST to Sunday 02:00 EST, then 03:00 EDT starts
        # = 03:00Z (Sat) to 07:00Z (Sun)
        assert len(result) >= 1

    def test_fall_back_repeated_time(self):
        """Fall back: repeated times are shown twice and covered both times."""
        ny = {
            "tz": "America/New_York",
            "hours": {"sun": ["00:00-03:00"]},
        }
        # 2025-11-02: clocks go from 01:59 EDT to 01:00 EST at 06:00Z
        # 00:00-03:00 EDT becomes 00:00 EDT to 03:00 EST
        # = 04:00Z to 08:00Z (four hours: 04:00-05:00 EDT, 05:00-06:00 EDT, 06:00-07:00 EST, 07:00-08:00 EST)
        result = free_slots([ny], "2025-11-02T00:00Z", "2025-11-03T00:00Z", 1)
        # Should have one continuous block covering the transition
        assert len(result) >= 1

    def test_fall_back_entry_in_repeated_time(self):
        """Entry covering the repeated time (shown both EDT and EST times)."""
        ny = {
            "tz": "America/New_York",
            "hours": {"sun": ["01:30-09:00"]},
        }
        # 01:30-09:00 on the fall-back day
        # 01:30-02:00 EDT (shown), skip to 01:00 EST, 01:00-01:59 EST (shown), then 02:00-09:00 EST
        result = free_slots([ny], "2025-11-02T00:00Z", "2025-11-03T00:00Z", 1)
        # Should cover the actual time, handling both EDT and EST renderings
        assert len(result) >= 1


class TestMultipleAttendees:
    """Test scheduling with multiple attendees."""

    def test_two_attendees_no_common_time(self):
        """Two attendees with no overlapping working hours."""
        tokyo = {"tz": "Asia/Tokyo", "hours": {d: ["09:00-17:00"] for d in WEEKDAYS}}
        la = {"tz": "America/Los_Angeles", "hours": {d: ["09:00-17:00"] for d in WEEKDAYS}}
        result = free_slots(
            [tokyo, la], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30
        )
        # Tokyo 09:00-17:00 JST = 00:00-08:00 UTC (Mon)
        # LA 09:00-17:00 PDT = 16:00-00:00 UTC (next day)
        # No overlap
        assert result == []

    def test_busy_period_one_attendee_affects_all(self):
        """Busy period of one attendee reduces available slots."""
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEKDAYS}}
        bob = {
            "tz": "UTC",
            "hours": {d: ["09:00-17:00"] for d in WEEKDAYS},
            "busy": [["2025-06-02T12:00:00Z", "2025-06-02T13:00:00Z"]],
        }
        result = free_slots(
            [alice, bob], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 30
        )
        # Only Alice is free during 12:00-13:00, so Bob's busy time removes it
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T13:00:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_multiple_attendees_different_working_hours(self):
        """Multiple attendees with different daily working hours."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-18:00"], "tue": ["10:00-19:00"]},
        }
        bob = {
            "tz": "UTC",
            "hours": {"mon": ["10:00-17:00"], "tue": ["09:00-18:00"]},
        }
        result_mon = free_slots([alice, bob], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        result_tue = free_slots([alice, bob], "2025-06-03T00:00Z", "2025-06-04T00:00Z", 30)
        # Monday: Alice 09:00-18:00, Bob 10:00-17:00 → overlap 10:00-17:00
        assert result_mon == [("2025-06-02T10:00:00Z", "2025-06-02T17:00:00Z")]
        # Tuesday: Alice 10:00-19:00, Bob 09:00-18:00 → overlap 10:00-18:00
        assert result_tue == [("2025-06-03T10:00:00Z", "2025-06-03T18:00:00Z")]


class TestTimestampFormats:
    """Test various timestamp formats."""

    def test_timestamp_with_z_suffix(self):
        """Timestamp with Z suffix (UTC)."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T10:00Z", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z")]

    def test_timestamp_with_positive_offset(self):
        """Timestamp with +HH:MM offset."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00:00+00:00", "2025-06-02T10:00:00+00:00", 30)
