class TestEdgeCases:
    """Test edge cases and boundary conditions."""

    def test_search_window_one_minute(self):
        """Search window of exactly one minute."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T09:01Z", 1)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T09:01:00Z")]

    def test_search_window_spans_multiple_weeks(self):
        """Search window spanning multiple weeks."""
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEKDAYS}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-16T00:00Z", 30)
        # Should have one slot per weekday in the range
        weekday_dates = [
            "2025-06-02",  # Mon
            "2025-06-03",  # Tue
            "2025-06-04",  # Wed
            "2025-06-05",  # Thu
            "2025-06-06",  # Fri
            "2025-06-09",  # Mon
            "2025-06-10",  # Tue
            "2025-06-11",  # Wed
            "2025-06-12",  # Thu
            "2025-06-13",  # Fri
        ]
        assert len(result) == len(weekday_dates)

    def test_exact_start_boundary(self):
        """Free period starting exactly at search window start."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 30)
        assert result[0][0] == "2025-06-02T09:00:00Z"

    def test_exact_end_boundary(self):
        """Free period ending exactly at search window end."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 30)
        assert result[0][1] == "2025-06-02T17:00:00Z"

    def test_working_hours_at_midnight(self):
        """Working hours covering midnight boundary."""
        alice = {"tz": "UTC", "hours": {"mon": ["23:00-24:00"], "tue": ["00:00-02:00"]}}
        result = free_slots([alice], "2025-06-02T22:00Z", "2025-06-03T03:00Z", 30)
        # Monday 23:00-midnight + Tuesday 00:00-02:00 should merge across the boundary
        assert len(result) >= 1

    def test_busy_period_touching_working_hours_boundary(self):
        """Busy period exactly at the boundary of working hours."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T17:00:00Z", "2025-06-02T18:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 30)
        # Busy period starts exactly when working hours end, should not affect result
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_result_output_format_utc(self):
        """Result timestamps are in UTC with Z suffix and seconds."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-10:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T10:00Z", 1)
        # Check format: YYYY-MM-DDTHH:MM:SSZ
        assert result[0][0] == "2025-06-02T09:00:00Z"
        assert result[0][1] == "2025-06-02T10:00:00Z"
        assert result[0][0].endswith("Z")
        assert result[0][1].endswith("Z")
        assert len(result[0][0]) == len("2025-06-02T09:00:00Z")

import pytest
from freebusy import free_slots

WEEK = ("mon", "tue", "wed", "thu", "fri")
WEEKEND = ("sat", "sun")
ALL_DAYS = WEEK + WEEKEND


class TestBasicFunctionality:
    """Test basic free_slots functionality with simple cases."""

    def test_single_attendee_one_day(self):
        """Single attendee with simple 9-5 working hours."""
        alice = {"tz": "UTC", "hours": {"fri": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-06T00:00Z", "2025-06-07T00:00Z", 1)
        assert result == [("2025-06-06T09:00:00Z", "2025-06-06T17:00:00Z")]

    def test_single_attendee_multiple_days(self):
        """Single attendee across multiple weekdays."""
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-07T00:00Z", 1)
        # June 2-6 is Mon-Fri
        assert len(result) == 5
        assert result[0] == ("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")
        assert result[4] == ("2025-06-06T09:00:00Z", "2025-06-06T17:00:00Z")

    def test_no_working_hours(self):
        """Attendee with no working hours defined."""
        alice = {"tz": "UTC", "hours": {}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        assert result == []

    def test_min_minutes_filtering(self):
        """Verify min_minutes parameter filters short slots."""
        alice = {"tz": "UTC", "hours": {"fri": ["09:00-17:00"]}}
        # 8 hours = 480 minutes
        result_30 = free_slots([alice], "2025-06-06T00:00Z", "2025-06-07T00:00Z", 30)
        result_600 = free_slots([alice], "2025-06-06T00:00Z", "2025-06-07T00:00Z", 600)

        assert len(result_30) == 1
        assert len(result_600) == 0

    def test_min_minutes_exact_boundary(self):
        """Slot exactly at min_minutes boundary is included."""
        alice = {"tz": "UTC", "hours": {"fri": ["09:00-17:00"]}}
        # 8 hours = 480 minutes, search for exactly 480
        result = free_slots([alice], "2025-06-06T00:00Z", "2025-06-07T00:00Z", 480)
        assert len(result) == 1

    def test_min_minutes_one(self):
        """min_minutes=1 includes very short slots."""
        alice = {"tz": "UTC", "hours": {"fri": ["09:00-09:01"]}}
        result = free_slots([alice], "2025-06-06T00:00Z", "2025-06-07T00:00Z", 1)
        assert len(result) == 1


class TestTimezones:
    """Test handling of different time zones."""

    def test_utc_timezone(self):
        """UTC timezone works correctly."""
        alice = {"tz": "UTC", "hours": {"fri": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-06T09:00Z", "2025-06-06T17:00Z", 1)
        assert result == [("2025-06-06T09:00:00Z", "2025-06-06T17:00:00Z")]

    def test_negative_offset_in_timestamp(self):
        """Timestamps with negative UTC offsets are parsed correctly."""
        alice = {"tz": "UTC", "hours": {"fri": ["09:00-17:00"]}}
        # Same instant as 2025-06-06T13:00Z is 2025-06-06T09:00-04:00
        result = free_slots([alice], "2025-06-06T09:00-04:00", "2025-06-06T17:00-04:00", 1)
        assert result == [("2025-06-06T13:00:00Z", "2025-06-06T21:00:00Z")]

    def test_positive_offset_in_timestamp(self):
        """Timestamps with positive UTC offsets are parsed correctly."""
        alice = {"tz": "UTC", "hours": {"fri": ["09:00-17:00"]}}
        # Same instant as 2025-06-06T13:00Z is 2025-06-06T22:00+09:00
        result = free_slots([alice], "2025-06-06T22:00+09:00", "2025-06-07T06:00+09:00", 1)
        assert result == [("2025-06-06T13:00:00Z", "2025-06-06T21:00:00Z")]

    def test_two_timezones_overlap(self):
        """Two attendees in different time zones with overlapping working hours."""
        ny = {"tz": "America/New_York", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        london = {"tz": "Europe/London", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        # June 2025: NY is UTC-4, London is UTC+1
        # NY 9:00-17:00 is 13:00-21:00 UTC
        # London 9:00-17:00 is 08:00-16:00 UTC
        # Overlap: 13:00-16:00 UTC (3 hours)
        result = free_slots([ny, london], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        assert len(result) == 1
        # 13:00-16:00 UTC on June 2 (Monday)
        assert result[0] == ("2025-06-02T13:00:00Z", "2025-06-02T16:00:00Z")

    def test_no_timezone_overlap(self):
        """Two attendees with non-overlapping working hours."""
        tokyo = {"tz": "Asia/Tokyo", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        honolulu = {"tz": "Pacific/Honolulu", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        # 17-hour time difference, no meaningful overlap
        result = free_slots([tokyo, honolulu], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        assert result == []

    def test_three_timezones(self):
        """Three attendees across different time zones."""
        ny = {"tz": "America/New_York", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        london = {"tz": "Europe/London", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        tokyo = {"tz": "Asia/Tokyo", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        # This is a challenging scenario; the overlap will be very small or non-existent
        result = free_slots([ny, london, tokyo], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        # Just verify it runs and returns a list
        assert isinstance(result, list)


