class TestBusyPeriods:
    """Test busy period handling."""

    def test_busy_period_basic(self):
        """Single busy period removes time from free slot."""
        alice = {
            "tz": "UTC",
            "hours": {"fri": ["09:00-17:00"]},
            "busy": [["2025-06-06T12:00Z", "2025-06-06T14:00Z"]],
        }
        result = free_slots([alice], "2025-06-06T00:00Z", "2025-06-07T00:00Z", 1)
        # Should split into two slots: 9-12 and 14-17
        assert len(result) == 2
        assert result[0] == ("2025-06-06T09:00:00Z", "2025-06-06T12:00:00Z")
        assert result[1] == ("2025-06-06T14:00:00Z", "2025-06-06T17:00:00Z")

    def test_busy_period_covers_all_work(self):
        """Busy period covering entire working hours results in no free time."""
        alice = {
            "tz": "UTC",
            "hours": {"fri": ["09:00-17:00"]},
            "busy": [["2025-06-06T09:00Z", "2025-06-06T17:00Z"]],
        }
        result = free_slots([alice], "2025-06-06T00:00Z", "2025-06-07T00:00Z", 1)
        assert result == []

    def test_busy_period_no_overlap(self):
        """Busy period outside working hours doesn't affect result."""
        alice = {
            "tz": "UTC",
            "hours": {"fri": ["09:00-17:00"]},
            "busy": [["2025-06-06T05:00Z", "2025-06-06T08:00Z"]],
        }
        result = free_slots([alice], "2025-06-06T00:00Z", "2025-06-07T00:00Z", 1)
        assert result == [("2025-06-06T09:00:00Z", "2025-06-06T17:00:00Z")]

    def test_multiple_busy_periods(self):
        """Multiple busy periods are handled correctly."""
        alice = {
            "tz": "UTC",
            "hours": {"fri": ["09:00-17:00"]},
            "busy": [
                ["2025-06-06T10:00Z", "2025-06-06T11:00Z"],
                ["2025-06-06T14:00Z", "2025-06-06T15:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-06T00:00Z", "2025-06-07T00:00Z", 1)
        # Should have three slots: 9-10, 11-14, 15-17
        assert len(result) == 3

    def test_overlapping_busy_periods(self):
        """Overlapping busy periods are merged."""
        alice = {
            "tz": "UTC",
            "hours": {"fri": ["09:00-17:00"]},
            "busy": [
                ["2025-06-06T10:00Z", "2025-06-06T12:00Z"],
                ["2025-06-06T11:00Z", "2025-06-06T13:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-06T00:00Z", "2025-06-07T00:00Z", 1)
        # Should have two slots: 9-10 (skipped due to min_minutes if too short) and 13-17
        assert len(result) >= 1

    def test_busy_period_touching(self):
        """Adjacent busy periods don't create false gaps."""
        alice = {
            "tz": "UTC",
            "hours": {"fri": ["09:00-17:00"]},
            "busy": [
                ["2025-06-06T10:00Z", "2025-06-06T12:00Z"],
                ["2025-06-06T12:00Z", "2025-06-06T14:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-06T00:00Z", "2025-06-07T00:00Z", 1)
        # Should have two slots: 9-10 and 14-17
        assert len(result) >= 1

    def test_busy_period_outside_window(self):
        """Busy periods outside search window are ignored."""
        alice = {
            "tz": "UTC",
            "hours": {"fri": ["09:00-17:00"]},
            "busy": [
                ["2025-06-06T05:00Z", "2025-06-06T08:00Z"],
                ["2025-06-06T18:00Z", "2025-06-06T20:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-06T09:00Z", "2025-06-06T17:00Z", 1)
        assert result == [("2025-06-06T09:00:00Z", "2025-06-06T17:00:00Z")]

    def test_busy_period_spans_days(self):
        """Busy period can span multiple days."""
        alice = {
            "tz": "UTC",
            "hours": {d: ["09:00-17:00"] for d in WEEK},
            "busy": [["2025-06-04T15:00Z", "2025-06-05T11:00Z"]],
        }
        result = free_slots([alice], "2025-06-04T00:00Z", "2025-06-06T00:00Z", 1)
        # June 4 (Wed): 9-15 free
        # June 5 (Thu): 11-17 free
        # June 6 (Fri): 9-17 free
        assert len(result) >= 1

    def test_busy_period_different_timezone(self):
        """Busy periods in different timezone are converted correctly."""
        alice = {
            "tz": "America/New_York",
            "hours": {"fri": ["09:00-17:00"]},
            "busy": [["2025-06-06T16:00-04:00", "2025-06-06T17:00-04:00"]],  # 16:00-17:00 EDT = 20:00-21:00 UTC
        }
        result = free_slots([alice], "2025-06-06T00:00Z", "2025-06-07T00:00Z", 1)
        # Friday June 6 2025 in NY (EDT, UTC-4): 9:00-17:00 EDT = 13:00-21:00 UTC
        # Busy 20:00-21:00 UTC, so free is 13:00-20:00 UTC
        assert len(result) >= 1

    def test_no_busy_periods(self):
        """Missing busy key means no busy periods."""
        alice = {"tz": "UTC", "hours": {"fri": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-06T00:00Z", "2025-06-07T00:00Z", 1)
        assert result == [("2025-06-06T09:00:00Z", "2025-06-06T17:00:00Z")]

    def test_empty_busy_list(self):
        """Empty busy list means no busy periods."""
        alice = {"tz": "UTC", "hours": {"fri": ["09:00-17:00"]}, "busy": []}
        result = free_slots([alice], "2025-06-06T00:00Z", "2025-06-07T00:00Z", 1)
        assert result == [("2025-06-06T09:00:00Z", "2025-06-06T17:00:00Z")]


class TestDSTHandling:
    """Test Daylight Saving Time edge cases."""

    def test_dst_spring_forward(self):
        """Test spring forward DST (clocks jump ahead)."""
        # 2025-03-09 in America/New_York: clocks jump from 02:00 EST to 03:00 EDT at 07:00 UTC
        alice = {
            "tz": "America/New_York",
            "hours": {"sun": ["02:00-04:00"]},
        }
        result = free_slots([alice], "2025-03-09T00:00Z", "2025-03-10T00:00Z", 1)
        # Entry "02:00-04:00" on Sunday: 02:00 EDT (03:00 UTC) to 04:00 EDT (08:00 UTC)
        # The time 02:30 EST doesn't exist
        assert len(result) >= 0  # Verify it doesn't crash

    def test_dst_fall_back(self):
        """Test fall back DST (clocks jump back)."""
        # 2025-11-02 in America/New_York: clocks jump from 01:59 EDT back to 01:00 EST at 06:00 UTC
        alice = {
            "tz": "America/New_York",
            "hours": {"sun": ["00:00-03:00"]},
        }
        result = free_slots([alice], "2025-11-02T00:00Z", "2025-11-03T00:00Z", 1)
        # Entry "00:00-03:00" covers repeated hours twice
        assert len(result) >= 0  # Verify it doesn't crash

    def test_dst_no_impact_outside_transition(self):
        """DST doesn't affect days far from transition."""
        alice = {"tz": "America/New_York", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        assert len(result) >= 0  # Just verify it works


