        # Same instant as 2025-06-06T13:00Z
        result = free_slots([alice], "2025-06-06T18:45+05:45", "2025-06-06T19:45+05:45", 1)
        assert len(result) >= 0

    def test_result_timestamp_format(self):
        """Result timestamps are in UTC with Z suffix and seconds."""
        alice = {"tz": "UTC", "hours": {"fri": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-06T09:00Z", "2025-06-06T10:00Z", 1)
        if result:
            start, end = result[0]
            assert start.endswith("Z")
            assert end.endswith("Z")
            assert ":" in start and start.count(":") == 2  # HH:MM:SS
            assert ":" in end and end.count(":") == 2


