class TestEdgeCases:
    """Test edge cases and boundary conditions."""

    def test_very_short_slot(self):
        """Single-minute slots are handled correctly."""
        alice = {"tz": "UTC", "hours": {"fri": ["09:00-09:01"]}}
        result = free_slots([alice], "2025-06-06T09:00Z", "2025-06-06T09:01Z", 1)
        assert result == [("2025-06-06T09:00:00Z", "2025-06-06T09:01:00Z")]

    def test_slot_exactly_at_midnight(self):
        """Slots at midnight boundaries are correct."""
        alice = {"tz": "UTC", "hours": {"fri": ["00:00-01:00"]}}
        result = free_slots([alice], "2025-06-06T00:00Z", "2025-06-06T01:00Z", 1)
        assert result == [("2025-06-06T00:00:00Z", "2025-06-06T01:00:00Z")]

    def test_multiple_free_slots_sorted(self):
        """Multiple free slots are returned in sorted order."""
        alice = {
            "tz": "UTC",
            "hours": {d: ["09:00-17:00"] for d in WEEK},
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-07T00:00Z", 1)
        # Verify sorted order
        for i in range(len(result) - 1):
            assert result[i][0] <= result[i + 1][0]

    def test_slots_across_timezone_boundaries(self):
        """Slots that span different attendees' midnight boundaries."""
        alice = {
            "tz": "America/New_York",
            "hours": {"fri": ["22:00-24:00"], "sat": ["00:00-06:00"]},
        }
        result = free_slots([alice], "2025-06-06T00:00Z", "2025-06-08T00:00Z", 1)
        # Should find slots that span the midnight transition
        assert len(result) >= 0

    def test_attendee_with_many_hours_entries(self):
        """Attendee with many working hour entries per day."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["08:00-09:00", "10:00-11:00", "12:00-13:00", "14:00-15:00"]},
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        assert len(result) == 4

    def test_many_attendees(self):
        """Function handles many attendees."""
        attendees = [
            {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
            for _ in range(5)
        ]
        result = free_slots(attendees, "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        # Should still work
        assert isinstance(result, list)

    def test_very_large_time_window(self):
        """Large time window is handled correctly."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-01-01T00:00Z", "2025-12-31T23:59Z", 1)
        # Should find many slots (all Mondays)
        assert len(result) > 50

    def test_narrow_free_window(self):
        """Very narrow search window with no free time."""
        alice = {
            "tz": "UTC",
            "hours": {"fri": ["09:00-17:00"]},
            "busy": [["2025-06-06T10:00Z", "2025-06-06T16:00Z"]],
        }
        result = free_slots([alice], "2025-06-06T10:00Z", "2025-06-06T10:30Z", 1)
        # Window entirely within busy period
