    def test_one_minute_window_at_slot_boundary(self):
        """One-minute window at exact slot boundary."""
        alice = {"tz": "UTC", "hours": {"fri": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-06T09:00Z", "2025-06-06T09:01Z", 1)
        assert result == [("2025-06-06T09:00:00Z", "2025-06-06T09:01:00Z")]

    def test_slot_requires_exact_min_minutes(self):
